CONFIG_CODE = 'from pathlib import Path\nfrom datetime import UTC, datetime\nimport threading, json\nMODE = "setup"\nFREE_GPU_CONFIRMED = False  # Metered existing units were explicitly approved; never claim free.\nEXISTING_UNITS_CONFIRMED = True\nMAX_EXISTING_COMPUTE_UNITS = 10\nBUNDLE_ARCHIVE = "/content/resolvedesk-colab-source.zip"\nEXPECTED_SOURCE_SHA256 = "65b9e93cd92fd3fb51d0bbbdde96df8cbacc54195c7b28c9c76fa90f1433eb4b"\nEXPECTED_PLAN_SHA256 = "a547fd0790ad2003fcd3dc0a990b581484bf5decd30222c87499237fd236f704"\nINITIALIZER_ARCHIVE = "/content/resolvedesk-initializer.zip"\nFINAL_ARCHIVE = "/content/resolvedesk-torch-formal-1344-complete.zip"\nWORKSPACE = "/content/resolvedesk-cuda-eval-002"\nPROCESS_DEADLINE_UTC = "2026-10-29T03:20:00+00:00"\nRUNTIME_STOP_UTC = "2026-10-29T03:30:00+00:00"\n# Official Colab runtime API, independent of whether the model process finishes.\nfrom google.colab import runtime as colab_runtime\nif "rd_runtime_stop_timer" not in globals():\n    seconds = (datetime.fromisoformat(RUNTIME_STOP_UTC) - datetime.now(UTC)).total_seconds()\n    assert 0 < seconds < 3 * 3600\n    def stop_own_runtime():\n        print("Budget resource deadline reached: releasing this Colab runtime.", flush=True)\n        colab_runtime.unassign()\n    rd_runtime_stop_timer = threading.Timer(seconds, stop_own_runtime)\n    rd_runtime_stop_timer.daemon = True\n    rd_runtime_stop_timer.start()\n    guard = {"run_id": "resolvedesk-cuda-eval-002", "max_existing_compute_units": 10,\n             "new_purchases_allowed": False, "renewal_allowed": False,\n             "observed_start_balance": 80, "observed_rate_units_per_hour": 1.07,\n             "rate_scope": "Colab UI estimate, not a guaranteed price or measured final usage",\n             "process_deadline_utc": PROCESS_DEADLINE_UTC, "runtime_stop_utc": RUNTIME_STOP_UTC,\n             "timer_armed_at_utc": datetime.now(UTC).isoformat(),\n             "timer_unassigns_runtime": True, "no_drive_mount": True}\n    Path("/content/resolvedesk-resource-guard.json").write_text(json.dumps(guard, indent=2))\nprint({"run_id": "resolvedesk-cuda-eval-002", "metered_existing_units_authorized": True,\n       "max_units": 10, "runtime_stop_utc": RUNTIME_STOP_UTC,\n       "timer_alive": rd_runtime_stop_timer.is_alive(), "model_calls_issued": 0})\n'

SETUP_CODE = 'import os\nimport subprocess\n\nif source_ready:\n    def checked(command, **kwargs):\n        return subprocess.run(command, cwd=workspace, check=True, **kwargs)\n\n    plan_file = workspace / "reports/cuda-eval2/analysis-plan.json"\n    assert EXPECTED_PLAN_SHA256 and hashlib.sha256(plan_file.read_bytes()).hexdigest() == EXPECTED_PLAN_SHA256\n    plan = json.loads(plan_file.read_text())\n    assert plan["run_id"] == "resolvedesk-cuda-eval-002"\n    os.environ["CUDA_VISIBLE_DEVICES"] = "0"\n    if MODE == "setup":\n        assert EXISTING_UNITS_CONFIRMED and MAX_EXISTING_COMPUTE_UNITS == 10\n        checked([sys.executable, "-B", "-c",\n                 "from training.colab.runner import validate_platform, probe_gpu; "\n                 "print(validate_platform()); print(probe_gpu(12288))"], timeout=35)\n        checked([sys.executable, "-m", "pip", "install", "--index-url",\n                 "https://download.pytorch.org/whl/cu128", "torch==2.11.0+cu128"])\n        checked([sys.executable, "-m", "pip", "install", "peft==0.19.1",\n                 "accelerate==1.14.0", "transformers==5.21.0", "safetensors==0.8.0",\n                 "numpy==2.5.4", "-e", str(workspace)])\n        # This unused optional package was incompatible in the original isolated runtime.\n        checked([sys.executable, "-m", "pip", "uninstall", "-y", "torchao"])\n        sys.path.insert(0, str(workspace))\n        from training.colab.bundle import import_initializer, verify_source\n        from training.colab.runner import provision_base\n        verify_source(workspace)\n        import_initializer(INITIALIZER_ARCHIVE, workspace)\n        final_path = Path(FINAL_ARCHIVE)\n        final_sha = "909a5d94662925c820811b359a4a464058579185ab627405ad716d0f749f3715"\n        assert hashlib.sha256(final_path.read_bytes()).hexdigest() == final_sha\n        members = {"train-1344/" + p for p in ["plan.json", "report.json", "formal-completion.json",\n                    "adapter/adapter_model.safetensors", "adapter/adapter_config.json"]}\n        members.add("formal-console.log")\n        with zipfile.ZipFile(final_path) as final_zip:\n            assert set(final_zip.namelist()) == members and len(final_zip.infolist()) == len(members)\n            assert sum(e.file_size for e in final_zip.infolist()) < 64 * 1024**2\n            for entry in final_zip.infolist():\n                assert not entry.is_dir() and not stat.S_ISLNK(entry.external_attr >> 16)\n                name = "reports/cuda-torch/probe-003/" + entry.filename\n                target = workspace / name\n                for parent in [target, *target.parents]:\n                    assert not parent.is_symlink()\n                content = final_zip.read(entry)\n                if target.exists():\n                    assert target.read_bytes() == content, "Never overwrite different evidence"\n                else:\n                    target.parent.mkdir(parents=True, exist_ok=True)\n                    with target.open("xb") as output:\n                        output.write(content)\n        provision_base(workspace)\n        checked([sys.executable, "-B", "-c",\n                 "from training.cuda_torch.train import dependency_precheck; "\n                 "print(dependency_precheck())"])\n        checked([sys.executable, "-B", "-m", "training.cuda_eval2.run", "preflight"])\n    elif MODE == "seal":\n        # The reviewed source bundle contains the original local CPU-sealed identity.\n        checked([sys.executable, "-B", "-c",\n                 "from pathlib import Path; "\n                 "from training.cuda_eval2.run import verify_identity; "\n                 "root = Path.cwd(); "\n                 "print(verify_identity(root / \'reports/cuda-eval2\', "\n                 "root / \'reports/cuda-torch/probe-003/train-1344/report.json\', "\n                 "root / \'reports/cuda-torch/probe-003/train-1344/adapter\', "\n                 "root / \'data/finetuning/retail-qlora-v6_1/best\', "\n                 "root / \'data/models/qwen3-4b-mlx\'))"])\n    else:\n        print("Setup/sealing skipped for this explicit mode.")\nelse:\n    print("Inspect mode: no package installation, downloads, GPU access or weight loading.")\n'

OVERLAY_IMPORT_CODE = 'import hashlib, json, stat, zipfile, subprocess, sys, os\nfrom pathlib import Path, PurePosixPath\nassert not FREE_GPU_CONFIRMED and EXISTING_UNITS_CONFIRMED\nassert hashlib.sha256(Path(BUNDLE_ARCHIVE).read_bytes()).hexdigest() == EXPECTED_SOURCE_SHA256\nassert rd_runtime_stop_timer.is_alive()\noverlay_path = Path("/content/resolvedesk-eval2-metered-overlay.zip")\nassert hashlib.sha256(overlay_path.read_bytes()).hexdigest() == EXPECTED_OVERLAY_SHA256\nallowed = {"training/cuda_eval2/budgeted_run.py", "tests/test_cuda_eval2_budget.py",\n           "training/colab/eval2_metered_ops.py", "reports/cuda-eval2/execution-addendum.json",\n           "reports/cuda-eval2/human-compute-authorization.json"}\nwith zipfile.ZipFile(overlay_path) as overlay:\n    entries = overlay.infolist()\n    assert len(entries) == len(allowed) + 1\n    assert set(overlay.namelist()) == allowed | {"execution-overlay-manifest.json"}\n    assert sum(e.file_size for e in entries) < 2 * 1024**2\n    manifest = json.loads(overlay.read("execution-overlay-manifest.json"))\n    assert set(manifest["files"]) == allowed\n    assert manifest["parent_source_zip_sha256"] == EXPECTED_SOURCE_SHA256\n    assert manifest["analysis_plan_sha256"] == EXPECTED_PLAN_SHA256\n    for name in sorted(allowed):\n        item = overlay.getinfo(name)\n        assert not stat.S_ISLNK(item.external_attr >> 16) and not item.is_dir()\n        path = PurePosixPath(name)\n        assert not path.is_absolute() and ".." not in path.parts\n        raw = overlay.read(name)\n        assert hashlib.sha256(raw).hexdigest() == manifest["files"][name]\n        target = workspace / name\n        for parent in [target, *target.parents]:\n            assert not parent.is_symlink()\n        if target.exists():\n            assert target.read_bytes() == raw, "Never overwrite a different execution artifact"\n        else:\n            target.parent.mkdir(parents=True, exist_ok=True)\n            with target.open("xb") as output: output.write(raw)\n# Use captured output so the notebook retains actual proof, not inherited child stdout.\nverify_code = """from pathlib import Path\nimport json, platform\nfrom training.colab.bundle import verify_source\nfrom training.colab.runner import probe_gpu\nfrom training.cuda_torch.train import dependency_precheck\nfrom training.cuda_eval2.evaluation import cpu_preflight\nfrom training.cuda_eval2.run import verify_identity\nfrom training.cuda_eval2.budgeted_run import verify_addendum\nroot=Path.cwd()\nsource=verify_source(root)\ndeps=dependency_precheck()\npre=cpu_preflight()\nidentity=verify_identity(root/\'reports/cuda-eval2\',root/\'reports/cuda-torch/probe-003/train-1344/report.json\',root/\'reports/cuda-torch/probe-003/train-1344/adapter\',root/\'data/finetuning/retail-qlora-v6_1/best\',root/\'data/models/qwen3-4b-mlx\')\naddendum=verify_addendum(require_not_expired=True)\nprint(json.dumps({\'run_id\':pre[\'run_id\'],\'source_files_verified\':len(source[\'files\']),\'frozen_sources_verified\':len(pre[\'source_inputs_sha256\']),\'cases\':len(pre[\'case_ids\']),\'before_sha\':identity[\'before_adapter_sha256\'],\'after_sha\':identity[\'after_adapter_sha256\'],\'authorization_mode\':addendum[\'authorization_mode\'],\'existing_CU_cap\':10,\'python\':platform.python_version(),\'gpu\':probe_gpu(12288),\'required_packages\':deps[\'required_packages\'],\'model_imported_or_called\':False},indent=2))\n"""\nprecheck = subprocess.run([sys.executable,"-B","-c",verify_code],cwd=workspace,\n                         capture_output=True,text=True,timeout=120)\n(workspace/"reports/cuda-eval2/prelaunch-cpu-console.log").write_text(precheck.stdout+precheck.stderr)\nprint(precheck.stdout,precheck.stderr,flush=True)\nprecheck.check_returncode()\nprint("Exact models/plan/new cohort and metered addendum verified; no model generation started.")\n'
